<?php requirePermission('suppliers');
if($_SERVER['REQUEST_METHOD']==='POST'){checkCsrf();$id=(int)($_POST['id']??0);$d=[trim($_POST['name']??''),trim($_POST['document']??''),trim($_POST['contact']??''),trim($_POST['phone']??''),trim($_POST['email']??''),trim($_POST['address']??'')];if($id){$pdo->prepare('UPDATE suppliers SET name=?,document=?,contact=?,phone=?,email=?,address=? WHERE id=?')->execute([...$d,$id]);}else{$pdo->prepare('INSERT INTO suppliers(name,document,contact,phone,email,address) VALUES(?,?,?,?,?,?)')->execute($d);}flash('success','Fornecedor salvo com sucesso.');redirect('index.php?page=suppliers');}
$edit=null;if(isset($_GET['edit'])){$st=$pdo->prepare('SELECT * FROM suppliers WHERE id=?');$st->execute([(int)$_GET['edit']]);$edit=$st->fetch();}$q=trim($_GET['q']??'');$st=$pdo->prepare('SELECT * FROM suppliers WHERE name LIKE ? OR document LIKE ? ORDER BY name');$st->execute(["%$q%","%$q%"]);$rows=$st->fetchAll();$title='Fornecedores';require __DIR__.'/../../includes/header.php';?>
<div class="page-head"><div><h1>Fornecedores</h1><p>Base de compras, contatos e reposição de estoque.</p></div></div><div class="grid two"><section class="panel"><h2><?=$edit?'Editar fornecedor':'Novo fornecedor'?></h2><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="id" value="<?=$edit['id']??0?>"><label class="span2">Razão/Nome<input name="name" required value="<?=e($edit['name']??'')?>"></label><label>CPF/CNPJ<input name="document" value="<?=e($edit['document']??'')?>"></label><label>Contato<input name="contact" value="<?=e($edit['contact']??'')?>"></label><label>Telefone<input name="phone" value="<?=e($edit['phone']??'')?>"></label><label>E-mail<input type="email" name="email" value="<?=e($edit['email']??'')?>"></label><label class="span2">Endereço<textarea name="address"><?=e($edit['address']??'')?></textarea></label><button class="btn primary">Salvar fornecedor</button></form></section><section class="panel"><form class="search"><input name="q" placeholder="Buscar fornecedor..." value="<?=e($q)?>"><button class="btn">Buscar</button></form><table><thead><tr><th>Fornecedor</th><th>Documento</th><th>Contato</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><strong><?=e($r['name'])?></strong><small><?=e($r['email'])?></small></td><td><?=e($r['document'])?></td><td><?=e($r['phone'])?></td><td><a href="index.php?page=suppliers&edit=<?=$r['id']?>">Editar</a></td></tr><?php endforeach;?></tbody></table></section></div><?php require __DIR__.'/../../includes/footer.php';?>
